    /**
     * This function takes a string and returns the maximum number of "a"s
     * that can be replaced with "b"s such that the string still contains at least one "a".
     *
     * The function works by finding the first occurrence of 'a' or 'A' and counting how many
     * consecutive 'a's or 'A's are there. It then calculates the maximum number of replacements
     * as the count minus one, ensuring at least one 'a' remains.
     *
     * @param s The string to be transformed.
     * @return The maximum number of "a"s that can be replaced with "b"s.
     */
    public static int maxReplaceAWithB(String s) {
        int index = findFirstA(s);
        if (index == -1) {
            return 0; // No 'a' found, cannot replace anything.
        }

        int count = 0;
        while (index != -1) {
            count++;
            index = s.indexOf('a', index + 1);
        }

        return count - 1; // Subtract one to ensure at least one 'a' remains.
    }

    public static void main(String[] args) {
        String inputString = "abacaba";
        System.out.println(maxReplaceAWithB(inputString)); // Output should be the maximum number of 'a's that can be replaced.
