    /**
     * The main function that implements QuickSort.
     *
     * @param array $array The array to be sorted.
     * @param int $low Starting index.
     * @param int $high Ending index.
     */
    private function quickSort(array &$array, int $low, int $high)
    {
        if ($low < $high) {
            // Partition the array and get the pivot index
            $pi = $this->partition($array, $low, $high);

            // Recursively sort elements before and after partition
            $this->quickSort($array, $low, $pi - 1);
            $this->quickSort($array, $pi + 1, $high);
        }
    }

    /**
     * This function takes last element as pivot, places the pivot element at its correct
     * position in sorted array, and places all smaller (smaller than pivot) to left of
     * pivot and all greater elements to right of pivot.
     *
     * @param array $array The array to be partitioned.
     * @param int $low Starting index.
     * @param int $high Ending index.
     * @return int The partitioning index.
     */
    private function partition(array &$array, int $low, int $high)
    {
        $pivot = $array[$high];
        $i = $low - 1; // Index of smaller element

        for ($j = $low; $j < $high; $j++) {
            // If current element is smaller than or equal to pivot
            if ($array[$j] <= $pivot) {
                $i++; // Increment index of smaller element
                $temp = $array[$i];
                $array[$i] = $array[$j];
                $array[$j] = $temp;
            }
        }

        // Swap the pivot element with the element at i+1
        $temp = $array[$i + 1];
        $array[$i + 1] = $array[$high];
        $array[$high] = $temp;

        return $i + 1;
    }
}

