ig.module(
    'game.entities.player'
)
.requires(
    'impact.entity',
    'impact.game',
    'impact.sound',
    'plugins.box2d',
    'game.entities.bullet',
    'game.entities.tank',
    'game.entities.missile',
    'game.entities.explosion'
)
.defines(function() {
    EntityPlayer = ig.Entity.extend({
        type: ig.Entity.TYPE.B | ig.Entity.TYPE.A,
        size: {x: 10, y: 10},
        offset: {x: 5, y: 5},
        speed: 200,
        health: 3,
        fireRate: 1000, // 1 second
        fireRateTimer: 0,
        gunCooldown: 0,
        gunCooldownTimer: 0,
        bullets: [],
        fireSound: new ig.Sound('media/player-fire.wav'),
        gunSound: new ig.Sound('media/gun.wav'),

        init: function(x, y, settings) {
            this.parent(x, y, settings);
            this.gunCooldown = 400; // 0.4 seconds
            this.gunCooldownTimer = this.gunCooldown;
        },

        update: function() {
            if (this.gunCooldownTimer > 0) {
                this.gunCooldownTimer -= ig.system.time.elapsedSinceLastUpdate;
            }

            if (ig.input.pressed('left')) {
                this.pos.x -= this.speed * ig.system.time.delta;
                this.flipX = true;
            } else if (ig.input.pressed('right')) {
                this.pos.x += this.speed * ig.system.time.delta;
                this.flipX = false;
            } else if (ig.input.pressed('up')) {
                this.pos.y -= this.speed * ig.system.time.delta;
            } else if (ig.input.pressed('down')) {
                this.pos.y += this.speed * ig.system.time.delta;
            }

            if (ig.input.pressed('fire') && this.gunCooldownTimer <= 0) {
                this.gunCooldownTimer = this.gunCooldown;
                this.gunSound.play();
                this.fireBullet();
            }
        },

        fireBullet: function() {
            var bullet = new EntityBullet(this.pos.x + this.size.x / 2, this.pos.y + this.size.y / 2, {
                velocity: this.gunSound.getVelocity(),
                angle: Math.PI / 2
            });
            this.bullets.push(bullet);
            ig.game.add(bullet);
            this.fireSound.play();
        },

        checkCollision: function(other) {
            if (other instanceof EntityTank || other instanceof EntityMissile) {
                this.health -= 1;
                if (this.health <= 0) {
                    ig.game.remove(this);
                    ig.game.spawnEntity(EntityExplosion, this.pos.x, this.pos.y);
                }
            }
        }
    });
});

