quint32 getHash(const QByteArray &data, quint32 seed)
{
    if (data.isEmpty())
        return 0;

    const quint32 m = 0x5bd1e995;
    quint32 h = seed ^ data.size();

    const quint8 *b = reinterpret_cast<const quint8*>(data.data());
    const int nblocks = data.size() / 4;

    for (int i = 0; i < nblocks; ++i) {
        quint32 k = 0;
        memcpy(&k, b + i * 4, 4);
        k *= m;
        k ^= k >> 23;
        k *= m;
        h *= m;
        h ^= k;
    }

    const quint8 *kb = b + nblocks * 4;
    quint32 k1 = 0;
    switch (data.size() - nblocks * 4) {
    case 3:
        k1 ^= kb[2] << 16;
    case 2:
        k1 ^= kb[1] << 8;
    case 1:
        k1 ^= kb[0];
        k1 *= m;
        h ^= k1;
        h *= m;
    }

    h ^= h >> 13;
    h *= m;
    h ^= h >> 15;

    return h;
}

