import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Problem {

    /**
     * Flattens a nested list (a list of lists) into a single flat list.
     *
     * @param nestedLists A list where each element is also a list that needs to be flattened.
     * @return A single list containing all the elements from the nested lists, in the same order.
     *
     * Example:
     * Problem.mergeNestedLists(Arrays.asList(Arrays.asList(1, 2, 3), Arrays.asList(4, 5), Arrays.asList(6)))
     * returns [1, 2, 3, 4, 5, 6]
     *
     * Problem.mergeNestedLists(Arrays.asList(Arrays.asList("a", "b"), Arrays.asList("c", "d", "e"), Arrays.asList("f")))
     * returns ["a", "b", "c", "d", "e", "f"]
     */
    public static <T> List<T> mergeNestedLists(List<List<T>> nestedLists) {
        List<T> flatList = new ArrayList<>();
        for (List<T> sublist : nestedLists) {
            flatList.addAll(sublist);
        }
        return flatList;
    }

    public static void main(String[] args) {
        // Unit tests for the mergeNestedLists function
        System.out.println(mergeNestedLists(Arrays.asList(Arrays.asList(1, 2, 3), Arrays.asList(4, 5), Arrays.asList(6))));
        // Output: [1, 2, 3, 4, 5, 6]

        System.out.println(mergeNestedLists(Arrays.asList(Arrays.asList("a", "b"), Arrays.asList("c", "d", "e"), Arrays.asList("f"))));
        // Output: [a, b, c, d, e, f]
    }
}

