    /**
     * Check if a given number is a power of two.
     *
     * A number is a power of two if it has exactly one bit set in its binary representation.
     * This can also be checked by seeing if the number is not zero and if the number
     * and its negation are the same when bitwise AND'ed.
     *
     * @param number The integer to be checked.
     * @return true if the number is a power of two, false otherwise.
     */
    public static boolean isPowerOfTwo(int number) {
        return number != 0 && (number & (number - 1)) == 0;
    }

    public static void main(String[] args) {
        // Unit tests for isPerfectSquare function
        System.out.println(isPerfectSquare(1));   // Output: true
        System.out.println(isPerfectSquare(16));  // Output: true
        System.out.println(isPerfectSquare(14));  // Output: false

        // Unit tests for isPowerOfTwo function
        System.out.println(isPowerOfTwo(1));   // Output: true
        System.out.println(isPowerOfTwo(2));   // Output: true
        System.out.println(isPowerOfTwo(3));   // Output: false
        System.out.println(isPowerOfTwo(4));   // Output: true
        System.out.println(isPowerOfTwo(16));  // Output: true
        System.out.println(isPowerOfTwo(18));  // Output: false
    }
}

