class Solution {
public:
    bool wordPattern(string pattern, string str) {
        unordered_map<char, string> m;
        vector<string> v;
        int i = 0, j = 0;
        while(i < str.size()) {
            if(str[i] == ' ') {
                v.push_back(str.substr(j, i - j));
                j = i + 1;
            }
            ++i;
        }
        v.push_back(str.substr(j, i - j));
        if(v.size() != pattern.size()) return false;
        for(int k = 0; k < v.size(); ++k) {
            if(m.find(pattern[k]) == m.end()) {
                m[pattern[k]] = v[k];
            } else {
                if(m[pattern[k]] != v[k]) return false;
            }
        }
        return true;
    }
};
