\begin{lemma}\label{lem:4.1}
Let $a_1, a_2, b_1, b_2$ be non-negative numbers and let $p, q > 1$ such that $\frac{1}{p} + \frac{1}{q} = 1$. Then we have
\begin{equation*}
a_1b_1 + a_2b_2 \leq (a_1^p + a_2^p)^{\frac{1}{p}}(b_1^q + b_2^q)^{\frac{1}{q}}.
\end{equation*}
\end{lemma}
\begin{proof}
This is just the application of H\"older's inequality to the function $f(x) = a_1^{px}a_2^{p(1-x)} + b_1^{qx}b_2^{q(1-x)}$ for $x \in [0, 1]$ with $p, q > 1$ such that $\frac{1}{p} + \frac{1}{q} = 1$.
\end{proof}

\begin{corollary}\label{cor:4.2}
Let $a_1, a_2, b_1, b_2$ be non-negative numbers and let $p, q > 1$ such that $\frac{1}{p} + \frac{1}{q} = 1$. Then we have
\begin{equation*}
(a_1b_1 + a_2b_2)^r \leq (a_1^p + a_2^p)^{\frac{r}{p}}(b_1^q + b_2^q)^{\frac{r}{q}}
\end{equation*}
for any $r > 0$.
\end{corollary}
\begin{proof}
We have by Lemma \ref{lem:4.1} that 
\begin{align*}
(a_1b_1 + a_2b_2)^r & \leq ((a_1b_1 + a_2b_2)(b_1^q + b_2^q))^{\frac{r}{q}} \\
& = ((a_1b_1 + a_2b_2)b_1^q + (a_1b_1 + a_2b_2)b_2^q)^{\frac{r}{q}} \\
& \leq (a_1b_1^q + a_2b_2^q + a_1b_2^q + a_2b_1^q)^{\frac{r}{q}} \\
& \leq (a_1^p + a_2^p)^{\frac{r}{p}}(b_1^q + b_2^q)^{\frac{r}{q}}
\end{align*}
\end{proof}

\begin{proposition}\label{prop:4.3}
Let $f \in L^1(\mathbb{R}^N)$ and $g \in L^1(\mathbb{R}^N)$. Then we have
\begin{equation*}
\|fg\|_{L^1(\mathbb{R}^N)} \leq C_N \|f\|_{L^{\frac{2N}{N+2}}(\mathbb{R}^N)}\|g\|_{L^{\frac{2N}{N-2}}(\mathbb{R}^N)}
\end{equation*}
where $C_N$ is a positive constant depending only on $N$.
\end{proposition}
\begin{proof}
By using the change of variables $y = x - z$ and Fubini's theorem, we have
\begin{align*}
\int_{\mathbb{R}^N} |f(x)g(x)| dx & = \int_{\mathbb{R}^N} |f(x)g(x - x)| dx \\
& = \int_{\mathbb{R}^N} \left(\int_{\mathbb{R}^N} f(x)g(y) dy\right) |dx| \\
& = \int_{\mathbb{R}^N} \left(\int_{\mathbb{R}^N} f(x)g(y) dx\right) |dy| \\
& = \int_{\mathbb{R}^N} |g(y)| \left(\int_{\mathbb{R}^N} f(x) |dx|\right) |dy| \\
& = \|g\|_{L^1(\mathbb{R}^N)} \|f\|_{L^1(\mathbb{R}^N)}
\end{align*}
Since $\frac{2N}{N+2}$ and $\frac{2N}{N-2}$ are conjugate exponents, by applying Corollary \ref{cor:4.2}, we obtain
