    // Unit tests for the computeFactorial function
    try {
        assert.equal(computeFactorial(5), 120, "Factorial of 5 should be 120");
        assert.equal(computeFactorial(0), 1, "Factorial of 0 should be 1");
        console.log("All tests passed!");
    } catch (error) {
        console.error(error);
    }
}

