function checkPalindrome(text) {
  return text === text.split('').reverse().join('');
}

/**
 * Finds the longest palindromic substring within the given string `inputString`.
 * 
 * This function uses a dynamic programming approach to identify the longest
 * palindromic substring in O(n^2) time complexity and O(1) space complexity.
 * 
 * @param {string} inputString - The string to search for the longest palindromic substring.
 * @returns {string} - The longest palindromic substring.
 */
function findLongestPalindromicSubstring(inputString) {
  const n = inputString.length;
  if (n === 0) {
    return "";
  }

  let start = 0;
  let maxLength = 1;

  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      if (checkPalindrome(inputString.substring(i, j + 1)) && (j - i + 1 > maxLength)) {
        start = i;
        maxLength = j - i + 1;
      }
    }
  }

  return inputString.substring(start, start + maxLength);
}

