public:
    CustomStack(int maxSize) {
        arr = new int[maxSize];
        index = new int[maxSize];
        top = -1;
        capacity = maxSize;
    }

    void addElement(int num) {
        if(top < capacity-1){
            top++;
            arr[top] = num;
            index[top] = 0;
        }
    }

    void pop() {
        if(top == -1)
            return;
        else{
            top--;
        }
    }

    int topElement() {
        if(top == -1)
            return -1;
        else
            return arr[top];
    }

    bool isFull() {
        return (top == capacity-1);
    }

    bool isEmpty() {
        return (top == -1);
    }
};

