    def get_available_moves(self):
        """Return a list of all available moves."""
        return [(i, j) for i in range(3) for j in range(3) if self.board[i][j] == 0]

    def make_move(self, move):
        """Make a move on the board and update the state."""
        i, j = move
        self.board[i][j] = self.current_player
        self.current_player = 1 if self.current_player == 2 else 2

    def undo_move(self, move):
        """Undo a move on the board and revert the state."""
        i, j = move
        self.board[i][j] = 0
        self.current_player = 1 if self.current_player == 2 else 2

    def evaluate(self):
        """Evaluate the current state of the game."""
        # Check rows, columns, and diagonals for a win
        for i in range(3):
            if self.board[i][0] == self.board[i][1] == self.board[i][2] != 0:
                return 1 if self.board[i][0] == self.current_player else -1
            if self.board[0][i] == self.board[1][i] == self.board[2][i] != 0:
                return 1 if self.board[0][i] == self.current_player else -1
        if self.board[0][0] == self.board[1][1] == self.board[2][2] != 0:
            return 1 if self.board[0][0] == self.current_player else -1
        if self.board[0][2] == self.board[1][1] == self.board[2][0] != 0:
            return 1 if self.board[0][2] == self.current_player else -1

        # Check for a draw
        if not any(0 in row for row in self.board):
            return 0

        # No winner or draw yet
        return None

    def is_game_over(self):
        """Check if the game is over (either a win or a draw)."""
        result = self.evaluate()
        return result is not None

    def minimax(self, depth, maximizing_player):
        """Minimax algorithm with alpha-beta pruning."""
        if depth == 0 or self.is_game_over():
            return self.evaluate()

        if maximizing_player:
            max_eval = float('-inf')
            for move in self.get_available_moves():
                self.make_move(move)
                eval = self.minimax(depth - 1, False)
                self.undo_move(move)
                max_eval = max(max_eval, eval)
            return max_eval
        else:
            min_eval = float('inf')
            for move in self.get_available_moves():
                self.make_move(move)
                eval = self.minimax(depth - 1, True)
                self.undo_move(move)
                min_eval = min(min_eval, eval)
            return min_eval

    def find_best_move(self):
        """Find the best move using the minimax algorithm."""
        best_move = None
        best_eval = float('-inf')
        for move in self.get_available_moves():
            self.make_move(move)
            eval = self.minimax(len(self.get_available_moves()) - 1, False)
            self.undo_move(move)
            if eval > best_eval:
                best_eval = eval
                best_move = move
        return best_move

