if (nums.empty()) return 0;
int left = 0, right = nums.size() - 1;

while (left < right) {
int mid = left + (right - left) / 2;
if (nums[mid] > nums[right]) { // the min is in the right part
left = mid + 1;
} else if (nums[mid] < nums[right]) { // the min is in the left part
right = mid; // or mid-1, because mid could be the min
