                        <a href="{{ route('password.reset', ['token' => $token, 'email' => $user->email]) }}" target="_blank" style="background-color: #007BFF; color: white; padding: 10px 20px; border-radius: 5px; text-decoration: none;">Reset Password</a>
                        <p>If you didn't request a password reset, please ignore this email.</p>
