    /// <param name="inputString">The input string to search for palindromic substrings.</param>
    /// <returns>A list containing all unique palindromic substrings of the input string.</returns>
    public static List<string> FindPalindromicSubstrings(string inputString)
    {
        HashSet<string> palindromes = new HashSet<string>();
        int n = inputString.Length;

        for (int i = 0; i < n; i++)
        {
            // Odd length palindromes
            ExpandAroundCenter(inputString, i, i, ref palindromes);

            // Even length palindromes
            ExpandAroundCenter(inputString, i, i + 1, ref palindromes);
        }

        return new List<string>(palindromes);
    }

    /// <summary>
    /// Expands around the center indices to find all palindromic substrings and adds them to the set.
    /// </summary>
    /// <param name="inputString">The input string.</param>
    /// <param name="left">The left index of the center.</param>
    /// <param name="right">The right index of the center.</param>
    /// <param name="palindromes">The set to store unique palindromic substrings.</param>
    private static void ExpandAroundCenter(string inputString, int left, int right, ref HashSet<string> palindromes)
    {
        while (left >= 0 && right < inputString.Length && inputString[left] == inputString[right])
        {
            palindromes.Add(inputString.Substring(left, right - left + 1));
            left--;
            right++;
        }
    }
}

