import java.util.Arrays;
import java.util.List;

public class Problem {

    /**
     * Check if a given sequence of numbers appears in a list.
     *
     * This method iterates over the list `numberList` to check if the subsequence `targetSequence`
     * appears in it. The method returns true if the sequence is found, otherwise false.
     *
     * @param numberList The list of integers to be checked.
     * @param targetSequence The sequence of integers to look for in the list.
     * @return true if the sequence is found in the list, false otherwise.
     */
    public static boolean containsSubsequence(List<Integer> numberList, List<Integer> targetSequence) {
        int seqLen = targetSequence.size();
        for (int i = 0; i <= numberList.size() - seqLen; i++) {
            if (numberList.subList(i, i + seqLen).equals(targetSequence)) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        // Unit tests for the containsSubsequence method
        System.out.println(containsSubsequence(Arrays.asList(1, 4, 2, 1, 2, 3), Arrays.asList(1, 2, 3))); // Output: true
        System.out.println(containsSubsequence(Arrays.asList(1, 2, 4, 1, 2, 3, 4), Arrays.asList(1, 3, 4))); // Output: false
    }
}

