s 仅由小写英文字母组成

### 解题思路
此处撰写解题思路

### 代码

```cpp
class Solution {
public:
    int distinctEchoSubstrings(string s) {
        int n = s.size();
        unordered_map<int, int> mp;
        int ans = 0;
        for(int i = 0; i < n; i++) {
            int cnt[26] = {0};
            for(int j = i; j < n; j++) {
                int c = s[j] - 'a';
                if(cnt[c] == 0) {
                    mp[(j - i + 1) << 16 | c]++;
                }
                cnt[c]++;
            }
        }

        for(auto [key, val] : mp) {
            if(val > 1) ans++;
        }

        return ans;
    }
};
```


