/**
 * Checks if the input string contains valid parentheses.
 * 
 * This function determines if the given string `input` consisting of characters '(', ')', '{', '}', '[' and ']' is valid.
 * A string is considered valid if:
 * - Open brackets are closed by the same type of brackets.
 * - Open brackets are closed in the correct order.
 * 
 * @param input The string containing only the characters '(', ')', '{', '}', '[' and ']'.
 * @returns true if the string is valid, false otherwise.
 * 
 * Example:
 * >>> isValidParentheses("()")
 * true
 * >>> isValidParentheses("()[]{}")
 * true
 * >>> isValidParentheses("(]")
 * false
 * >>> isValidParentheses("([)]")
 * false
 * >>> isValidParentheses("{[]}")
 * true
 */
function isValidParentheses(input: string): boolean {
    // Early return if the length of the string is odd
    if (input.length % 2 !== 0) {
        return false;
    }

    // Mapping of closing to opening parentheses
    const parenthesesMap: { [key: string]: string } = { ')': '(', '}': '{', ']': '[' };
    // Using Stack for efficient pop from the end
    const stack = new Stack<string>();

    for (const char of input) {
        if (char in parenthesesMap) {
            // If stack is empty or top of the stack doesn't match the corresponding opening bracket
            if (stack.isEmpty() || stack.pop() !== parenthesesMap[char]) {
                return false;
            }
        } else {
            // Push the opening bracket onto the stack
            stack.push(char);
        }
    }

    // If stack is empty, all parentheses were properly closed
    return stack.isEmpty();
}

