bool isValidDecimal(const std::string& str) {
    // Check if the string contains only digits and decimal point
    std::string validChars = "0123456789.";
    int countDot = 0;
    int len = str.length();
    for (int i = 0; i < len; i++) {
        if (validChars.find(str[i]) == std::string::npos) {
            return false;
        } else if (str[i] == '.') {
            countDot++;
        }
    }
    // A valid decimal number can have at most one decimal point
