 * (ignoring spaces, punctuation, and capitalization).
 *
 * @param {string} wordOrPhrase - The word or phrase to check for being a palindrome.
 * @returns {boolean} - True if the input is a palindrome, false otherwise.
 */
function isPalindrome(wordOrPhrase) {
  // Remove all non-alphanumeric characters and convert to lowercase
  const cleanedInput = wordOrPhrase.replace(/[\W_]/g, '').toLowerCase();
  return isStringPalindrome(cleanedInput);
}

