class Solution {
public:
    string makeLargestSpecial(string S) {
        int cnt = 0, i = 0;
        vector<string> v;

        for(int j = 0; j < S.size(); ++j) {
            if(S[j] == '1') cnt++;
            else cnt--;

            if(cnt == 0) {
                v.push_back("1" + makeLargestSpecial(S.substr(i+1, j-i-1)) + "0");
                i = j+1;
            }
        }

        sort(v.begin(), v.end(), greater<string>());
        string ans = "";

        for(auto x : v) ans += x;

        return ans.substr(0, min(ans.size(), (int)S.size()-k));
    }
};
