import java.util.Arrays;

public class Problem {

    /**
     * Find the longest common prefix string amongst an array of strings.
     *
     * If there is no common prefix, return an empty string "".
     *
     * @param words An array of strings to be analyzed for common prefixes.
     * @return The longest common prefix or an empty string if none is found.
     */
    public static String findLongestCommonPrefix(String[] words) {
        if (words == null || words.length == 0) {
            return "";
        }

        // Sort the array, so the first and last items will determine the common prefix
        Arrays.sort(words);

        // Take the first and last strings in the sorted array
        String firstWord = words[0];
        String lastWord = words[words.length - 1];

        // Compare characters of the first and last strings until they differ
        int i = 0;
        while (i < firstWord.length() && i < lastWord.length() && firstWord.charAt(i) == lastWord.charAt(i)) {
            i++;
        }

        // Return the common prefix between the first and last strings
        return firstWord.substring(0, i);
    }

    // Main function to test the generated function
    public static void main(String[] args) {
        System.out.println(findLongestCommonPrefix(new String[]{"flower", "flow", "flight"})); // Output: 'fl'
        System.out.println(findLongestCommonPrefix(new String[]{"dog", "racecar", "car"}));    // Output: ''
    }
}

